import "./form-input.styles.css";

const FormInput = ({ label, inputOptions }) => {
    return(
        <div className="group">
            <input className="form-input" {...otherProps} />
            {label && (
                <label 
                    className={`${
                        inputOptions.value.length ? "shrink" : ""
                    } form-input-label`}
                >
                    {label}
                </label>
            )}
            

        </div>
    );
};


export default FormInput;
